S.T('57-01', '01｜莉莉和闺蜜在舞池里跳舞，闺蜜喊着去拿酒走开', 8, CLUB,
    [P('lily_bar', 'left', "dancing in profile facing frame-right with her arms raised, her hips swaying", 'Chloe', 'her lips parted in an easy carefree laugh, her brows lifted'),
     P('chloe_friend', 'right', "dancing in profile facing frame-left with a hand lifted in a wave, laughing", 'Lily', 'her mouth open in a laugh, her brows lifted')],
    'Medium-wide shot, both women from the head to the knees, in the middle third of the frame, on the packed dance floor of the club.',
    "<chloe_friend> leans in toward <lily_bar> and shouts the line to <lily_bar> over the pounding bass, laughing, then points toward the bar at frame-right and weaves away through the dancers; <lily_bar> laughs, her eyes following her friend, and keeps dancing, her hips swaying and her hair swinging, her lips parted in an easy carefree laugh.",
    "克洛伊凑近莉莉，在重低音里笑着对莉莉喊出那句话，然后指向画面右边的吧台，从舞者中间挤着走开；莉莉笑着，眼睛目送着闺蜜，继续跳舞，腰肢摇摆、头发甩动，嘴唇微张是轻松随意的笑。",
    voiced('Pounding electronic dance music with a heavy bass beat and the buzz of a crowd.', '震耳的电子舞曲、沉重的低音节拍和人群的嘈杂声。'),
    lines=[('chloe_friend', "I'll grab us drinks!", 1.0, 'Lily')],
    cam=('The camera pushes in slowly until Lily fills the middle third of the frame.', '镜头慢慢推近，直到莉莉占满画面中间三分之一。'),
    bg=BG_DANCERS, holds='The frame holds Lily, Chloe and a crowd of dancers behind them.',
    groups=[DANCERS], room={'Lily', 'Chloe', 'Dancers'}, exit={'Chloe'}, new=True,
    st={'Lily': (LB, LB), 'Chloe': ('银色亮片迷你裙，在舞池里', None)})

S.T('57-02', '02｜搭讪男端着两杯酒挤到她身边：美女，一个人？', 10, CLUB,
    [P('brad_creep', 'left', "squeezing in beside her in profile facing frame-right, a drink in each hand, leaning his head toward her", 'Lily', 'a cocky leer on his lips, his brows lifted'),
     P('lily_bar', 'right', "dancing slowly in profile facing frame-left", 'Brad', 'her lips pressed flat, her brows level')],
    'Medium two-shot, both from the head to the waist, in the middle third of the frame, on the packed dance floor of the club.',
    "<brad_creep> leans in close to <lily_bar> and speaks the first line to <lily_bar> with a leer, then the second line to <lily_bar>, a glass in each hand, his bleary eyes on her face. <lily_bar> stops dancing and looks at him without expression, her lips pressed flat and her brows level.",
    "布拉德凑近莉莉，带着邪笑对莉莉说出第一句，再对莉莉说出第二句，两只手各端一杯酒，迷离的眼睛盯着她的脸。莉莉停下舞步，面无表情地看着他，嘴唇抿成一条线，眉毛平直。",
    voiced('Pounding electronic dance music with a heavy bass beat and the buzz of a crowd.', '震耳的电子舞曲、沉重的低音节拍和人群的嘈杂声。'),
    lines=[('brad_creep', "Pretty lady, all alone?", 1.0, 'Lily'), ('brad_creep', "Too dangerous here, honey.", 5.0, 'Lily')],
    bg=BG_DANCERS, holds='The frame holds Lily, Brad and a crowd of dancers behind them.',
    groups=[DANCERS], enter={'Brad'},
    st={'Lily': (LB, LB_COLD), 'Brad': ('粉色西装外套，两手各端一杯酒', '粉色西装外套，两手各端一杯酒')})

S.T('57-03', '03｜莉莉冷冷地回：很危险，离我远点，我老公是个控制狂', 10, CLUB,
    [P('brad_creep', 'left', "standing close beside her in profile facing frame-right, a drink in each hand, still leaning toward her", 'Lily', 'a cocky leer on his lips, his brows lifted'),
     P('lily_bar', 'right', "standing in profile facing frame-left with her arms crossed", 'Brad', 'her lips pressed flat, her brows low')],
    'Medium two-shot, both from the head to the waist, in the middle third of the frame, on the packed dance floor of the club.',
    "<lily_bar> speaks the first line to <brad_creep> in a cold flat voice, then the second line to <brad_creep>, her hazel-green eyes steady on his face, her arms crossed, her lips pressed flat and her brows low. <brad_creep> grins at her unimpressed, his eyes on her face.",
    "莉莉用冰冷平淡的声音对布拉德说出第一句，再对布拉德说出第二句，榛绿色的眼睛稳稳地看着他的脸，双臂交叉，嘴唇抿平，眉毛压低。布拉德不当回事地咧嘴，眼睛看着她的脸。",
    voiced('Pounding electronic dance music with a heavy bass beat and the buzz of a crowd.', '震耳的电子舞曲、沉重的低音节拍和人群的嘈杂声。'),
    lines=[('lily_bar', "It is dangerous. Back off.", 1.0, 'Brad'), ('lily_bar', "My husband is extremely possessive.", 5.0, 'Brad')],
    cam=CAM_TWO_PUSH, bg=BG_DANCERS, holds='The frame holds Lily, Brad and a crowd of dancers behind them.', groups=[DANCERS], dep=True,
    st={'Lily': (LB_COLD, LB_COLD), 'Brad': ('粉色西装外套，两手各端一杯酒', '粉色西装外套，两手各端一杯酒')})

S.T('57-04', '04｜他嘲笑她：你老公不行啊，手伸向她的腰', 10, CLUB,
    [P('brad_creep', 'left', "standing close beside her in profile facing frame-right, a drink in his left hand and his right hand lifting toward her waist", 'Lily', 'a cocky leer on his lips, his brows lifted'),
     P('lily_bar', 'right', "standing in profile facing frame-left with her arms crossed", 'Brad', 'her lips curled in disgust, her brows low')],
    'Medium two-shot, both from the head to the waist, in the middle third of the frame, on the packed dance floor of the club.',
    "<brad_creep> speaks the first line to <lily_bar> with a leer, then the second line to <lily_bar>, his right hand drifting toward her waist, his bleary eyes on her face. <lily_bar> stares him down, her arms crossed, her lips curled in disgust and her brows low.",
    "布拉德带着邪笑对莉莉说出第一句，再对莉莉说出第二句，右手慢慢往她的腰移去，迷离的眼睛盯着她的脸。莉莉死死瞪着他，双臂交叉，嘴唇厌恶地撇着，眉毛压低。",
    voiced('Pounding electronic dance music with a heavy bass beat and the buzz of a crowd.', '震耳的电子舞曲、沉重的低音节拍和人群的嘈杂声。'),
    lines=[('brad_creep', "Married and out partying?", 1.0, 'Lily'), ('brad_creep', "Your husband must be weak.", 5.0, 'Lily')],
    bg=BG_DANCERS, holds='The frame holds Lily, Brad and a crowd of dancers behind them.', groups=[DANCERS], dep=True,
    trigger="Your husband must be weak.",
    st={'Lily': (LB_COLD, LB_COLD), 'Brad': ('粉色西装外套，两手各端一杯酒', '右手伸向她的腰，一只手拿着酒')})

S.T('57-05', '05｜音乐被刺耳的盲音切断，激光熄灭，所有人定住转头看门', 5, CLUB_DARK,
    [P('brad_creep', 'left', "frozen in profile facing frame-right with his right hand an inch from her waist and a drink in his left hand, his head turning toward the steel door", 'obj:the steel entrance door at the back of the room at frame-right', 'his mouth hanging open mid-word, his brows pulled up'),
     P('lily_bar', 'right', "standing in profile facing frame-left with her arms crossed, her head turning toward the steel door", 'obj:the steel entrance door at the back of the room at frame-right', 'her lips parted, her brows pulled together')],
    'Wide shot of the whole club with the two of them in the middle third of the frame, in the club.',
    "The pounding bass chokes into a harsh metallic screech and dies, the neon lasers cut out and only dim red emergency strips glow; every dancer freezes and turns toward the steel door at frame-right; <brad_creep> freezes with his hand an inch from <lily_bar>'s waist, his mouth hanging open mid-word and his brows pulled up, his eyes darting to the door; <lily_bar> turns only her head toward the door, her lips parted and her brows pulled together.",
    "重低音突然卡壳成一声刺耳的金属盲音然后断掉，霓虹激光全灭、只剩昏暗的红色应急灯条；所有舞者定住，朝画面右边的钢门转头；布拉德的手停在莉莉腰边一寸，嘴巴半张在半句话里，眉毛上提，眼睛瞟向大门；莉莉只转头看向门，嘴唇微张，眉头皱紧。",
    breathy('The pounding bass chokes into a harsh metallic screech and then a stunned silence with a faint electrical hiss.', '重低音卡壳成一声刺耳的金属盲音，然后是震惊的寂静和细微的电流嘶声。'),
    bg="Behind them the crowd of dancers stands frozen with their heads turned toward the steel door, clearly visible and in sharp focus.",
    holds='The frame holds Lily, Brad and a frozen crowd of dancers behind them.', groups=[DANCERS], dep=True,
    effect="Your husband must be weak.",
    st={'Lily': (LB_COLD, LB_COLD), 'Brad': ('右手伸向她的腰，一只手拿着酒', '定住，回头看门')})

S.T('57-06', '06｜无人镜头：厚重的铁门被连根拔起，变形地躺在吧台尽头', 6, CLUB_DARK, [],
    'Wide shot of the back right of the club with the empty doorway and the far end of the bar counter, in the middle third of the frame, no person in the frame.',
    "The heavy steel soundproof door lies buckled and torn from its hinges across the far end of the bar counter, bottles toppling and shattering off the shelves behind it and rolling across the counter; dust and smoke drift out of the empty doorway into the silent club, the red emergency strips pulsing on the wrecked metal.",
    "厚重的钢制隔音门被连根扯下、变形地横在吧台尽头，它后面的酒瓶一个个倒下、碎在架子上、在吧台上滚动；灰尘和烟从空荡荡的门洞飘进寂静的酒吧，红色应急灯条在变形的金属上一明一暗。",
    breathy('A last bottle shattering, glass rolling across the counter and a heavy metallic groan in a silent room.', '最后一只酒瓶碎裂、碎玻璃在吧台上滚动，和寂静里一声沉重的金属呻吟。'),
    cam=('The camera pushes in slowly until the empty doorway fills the frame.', '镜头慢慢推近，直到空荡荡的门洞占满画面。'),
    holds='The frame holds the wrecked doorway, the torn steel door and the bar counter, and no person.', dep=True)

